 public function createDraft(string $b,array $in):array{
  self::keys($in,['documentType','customer','items','settingsOverrides','isOfficial','address','shippingMethod','validityDays','notes']);$type=$in['documentType']??'proforma';if(!in_array($type,['proforma','invoice'],true))throw new SalesValidationException('document_type_invalid');$c=$in['customer']??null;if(!is_array($c))throw new SalesValidationException('customer_required');self::keys($c,['id','displayName','phone','nationalId']);$name=self::text($c['displayName']??'',160,'customer_name',true);$phone=trim((string)($c['phone']??''));CustomerDirectory::mobile($phone);$official=($in['isOfficial']??false)===true;$national=CustomerDirectory::nationalId((string)($c['nationalId']??''),$official);$address=self::text($in['address']??'',500,'customer_address');$notes=self::text($in['notes']??'',2000,'notes');$shipping=(string)($in['shippingMethod']??'');if(!in_array($shipping,['','pickup','snapp_box','snapp_car','snapp_van','post','tipax'],true))throw new SalesValidationException('shipping_method_invalid');$validity=$in['validityDays']??null;if($validity!==null&&(!is_int($validity)||$validity<0||$validity>365))throw new SalesValidationException('validity_days_invalid');if($type==='invoice')$validity=null;$items=$in['items']??[];if(!is_array($items)||!array_is_list($items))throw new SalesValidationException('items_invalid');$settings=$this->settings->find($b)['settings']??SettingsSchema::defaults();$over=$in['settingsOverrides']??[];if(!is_array($over))throw new SalesValidationException('settings_overrides_invalid');$settings=SettingsSchema::mergeForDocument($settings,$over);$rate=$official?(int)($settings['financial']['taxRateBasisPoints']??1000):0;$tot=Money::calculate($items,0,0,$rate);$now=gmdate('Y-m-d H:i:s');$id=Uuid::v4();$this->pdo->beginTransaction();try{$cid=$this->resolveCustomer($b,$c,$name,$phone,$now);$sql='INSERT INTO sales_documents (id,business_id,customer_id,document_type,is_official,national_id,customer_address,shipping_method,validity_days,notes,tax_rate_basis_points,tax_total_base_unit,currency_unit,subtotal_base_unit,discount_base_unit,surcharge_base_unit,grand_total_base_unit,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)';$this->pdo->prepare($sql)->execute([$id,$b,$cid,$type,$official?1:0,$national,$address,$shipping,$validity,$notes,$rate,$tot['tax'],'rial',$tot['subtotal'],$tot['discount'],0,$tot['total'],$now,$now]);$this->replaceItems($id,$tot['items'],$now);$this->pdo->commit();}catch(\Throwable $e){$this->pdo->rollBack();throw$e;}return$this->get($b,$id);
 }
 public function updateDraft(string $b,string $id,array $in):array{self::keys($in,['documentType','customer','items','settingsOverrides','isOfficial','address','shippingMethod','validityDays','notes','version']);$d=$this->owned($b,$id);if($d['lifecycle_status']!=='draft')throw new SalesValidationException('finalized_document_immutable',409);$v=Money::amount($in['version']??null,'version');if(!array_key_exists('customer',$in)){$items=$in['items']??$this->items($id);if(!is_array($items))throw new SalesValidationException('items_invalid');$tot=Money::calculate(array_values($items),0,0,(int)$d['tax_rate_basis_points']);$now=gmdate('Y-m-d H:i:s');$this->pdo->beginTransaction();try{$s=$this->pdo->prepare("UPDATE sales_documents SET subtotal_base_unit=?,discount_base_unit=?,surcharge_base_unit=0,tax_total_base_unit=?,grand_total_base_unit=?,version=version+1,updated_at=? WHERE id=? AND business_id=? AND lifecycle_status='draft' AND version=?");$s->execute([$tot['subtotal'],$tot['discount'],$tot['tax'],$tot['total'],$now,$id,$b,$v]);if($s->rowCount()!==1)throw new SalesValidationException('draft_version_conflict',409);$this->replaceItems($id,$tot['items'],$now);$this->pdo->commit();}catch(\Throwable $e){$this->pdo->rollBack();throw$e;}return$this->get($b,$id);}$c=$in['customer']??null;if(!is_array($c))throw new SalesValidationException('customer_required');self::keys($c,['id','displayName','phone','nationalId']);$name=self::text($c['displayName']??'',160,'customer_name',true);$phone=trim((string)($c['phone']??''));CustomerDirectory::mobile($phone);$official=($in['isOfficial']??false)===true;$national=CustomerDirectory::nationalId((string)($c['nationalId']??''),$official);$address=self::text($in['address']??'',500,'customer_address');$notes=self::text($in['notes']??'',2000,'notes');$shipping=(string)($in['shippingMethod']??'');if(!in_array($shipping,['','pickup','snapp_box','snapp_car','snapp_van','post','tipax'],true))throw new SalesValidationException('shipping_method_invalid');$validity=$d['document_type']==='proforma'?($in['validityDays']??null):null;if($validity!==null&&(!is_int($validity)||$validity<0||$validity>365))throw new SalesValidationException('validity_days_invalid');$items=$in['items']??[];if(!is_array($items)||!array_is_list($items))throw new SalesValidationException('items_invalid');$set=$this->settings->find($b)['settings']??SettingsSchema::defaults();$rate=$official?(int)($set['financial']['taxRateBasisPoints']??1000):0;$tot=Money::calculate($items,0,0,$rate);$now=gmdate('Y-m-d H:i:s');$this->pdo->beginTransaction();try{$cid=$this->resolveCustomer($b,$c,$name,$phone,$now);$s=$this->pdo->prepare("UPDATE sales_documents SET customer_id=?,is_official=?,national_id=?,customer_address=?,shipping_method=?,validity_days=?,notes=?,tax_rate_basis_points=?,subtotal_base_unit=?,discount_base_unit=?,surcharge_base_unit=0,tax_total_base_unit=?,grand_total_base_unit=?,version=version+1,updated_at=? WHERE id=? AND business_id=? AND lifecycle_status='draft' AND version=?");$s->execute([$cid,$official?1:0,$national,$address,$shipping,$validity,$notes,$rate,$tot['subtotal'],$tot['discount'],$tot['tax'],$tot['total'],$now,$id,$b,$v]);if($s->rowCount()!==1)throw new SalesValidationException('draft_version_conflict',409);$this->replaceItems($id,$tot['items'],$now);$this->pdo->commit();}catch(\Throwable $e){$this->pdo->rollBack();throw$e;}return$this->get($b,$id);}
 public function finalize(string $b,string $id,bool $paid=false):array{$this->pdo->beginTransaction();try{$d=$this->owned($b,$id,true);if($d['lifecycle_status']==='issued'){$this->pdo->commit();return$this->get($b,$id);}if($d['lifecycle_status']!=='draft')throw new SalesValidationException('document_not_finalizable',409);if((int)$d['grand_total_base_unit']<1)throw new SalesValidationException('document_total_required');if($d['document_type']==='invoice'&&!$paid)throw new SalesValidationException('full_payment_confirmation_required');$set=$this->settings->find($b)['settings']??SettingsSchema::defaults();if((bool)$d['is_official'])$this->assertOfficialProfile($b,$set);$c=$this->customer($b,(string)$d['customer_id']);$number=$this->nextNumber($b,(string)$d['document_type'],$set);$amount=$d['document_type']==='invoice'?(int)$d['grand_total_base_unit']:0;$now=gmdate('Y-m-d H:i:s');$today=JalaliDate::today();$until=$d['validity_days']!==null?JalaliDate::plusDays($today['date'],(int)$d['validity_days']):null;$snap=$c+['address'=>$d['customer_address'],'isOfficial'=>(bool)$d['is_official'],'nationalId'=>$d['national_id']];$s=$this->pdo->prepare("UPDATE sales_documents SET lifecycle_status='issued',settlement_status=?,document_number=?,paid_amount_base_unit=?,settings_snapshot_json=?,customer_snapshot_json=?,issue_date=?,valid_until=?,version=version+1,issued_at=?,updated_at=? WHERE id=? AND business_id=? AND lifecycle_status='draft'");$s->execute([$amount?'paid':'unpaid',$number,$amount,DocumentSettingsSnapshot::toJson($set),json_encode($snap,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR),$today['date'],$until['date']??null,$now,$now,$id,$b]);$this->snapshot($b,$id,$now);$this->snapshotLogo($b,$id,$now);$this->pdo->commit();}catch(\Throwable $e){$this->pdo->rollBack();throw$e;}return$this->get($b,$id);}
 public function recordPayment(string $b,string $id,array $in):array{self::keys($in,['amountBaseUnit','paidAt','method','reference','note','idempotencyKey']);$a=Money::amount($in['amountBaseUnit']??null,'payment_amount');if($a<1)throw new SalesValidationException('payment_amount_invalid');$key=trim((string)($in['idempotencyKey']??''));if($key===''||strlen($key)>100)throw new SalesValidationException('idempotency_key_invalid');$this->pdo->beginTransaction();try{$p=$this->pdo->prepare('SELECT id FROM payments WHERE business_id=? AND idempotency_key=? LIMIT 1');$p->execute([$b,$key]);if($p->fetch()){$this->pdo->commit();return$this->get($b,$id);}$d=$this->owned($b,$id,true);if($d['document_type']!=='proforma'||$d['lifecycle_status']!=='issued')throw new SalesValidationException('payment_requires_issued_proforma',409);$old=(int)$d['paid_amount_base_unit'];$total=(int)$d['grand_total_base_unit'];if($a>$total-$old)throw new SalesValidationException('overpayment_rejected',409);$pid=Uuid::v4();$now=gmdate('Y-m-d H:i:s');$this->pdo->prepare('INSERT INTO payments (id,business_id,proforma_id,amount_base_unit,paid_at,method,reference_text,note,idempotency_key,created_at) VALUES (?,?,?,?,?,?,?,?,?,?)')->execute([$pid,$b,$id,$a,(string)($in['paidAt']??$now),substr((string)($in['method']??'manual'),0,32),substr((string)($in['reference']??''),0,160),substr((string)($in['note']??''),0,500),$key,$now]);$this->pdo->prepare('INSERT INTO payment_allocations (payment_id,document_id,amount_base_unit,created_at) VALUES (?,?,?,?)')->execute([$pid,$id,$a,$now]);$next=$old+$a;$this->pdo->prepare('UPDATE sales_documents SET paid_amount_base_unit=?,settlement_status=?,version=version+1,updated_at=? WHERE id=? AND business_id=?')->execute([$next,$next===$total?'paid':'partial',$now,$id,$b]);$this->pdo->commit();}catch(\Throwable $e){$this->pdo->rollBack();throw$e;}return$this->get($b,$id);}
 public function convert(string $b,string $id):array{$this->pdo->beginTransaction();try{$q=$this->pdo->prepare("SELECT id FROM sales_documents WHERE business_id=? AND source_document_id=? AND document_type='invoice' LIMIT 1");$q->execute([$b,$id]);if($f=$q->fetch()){$this->pdo->commit();return$this->get($b,(string)$f['id'],false);}$d=$this->owned($b,$id,true);if($d['document_type']!=='proforma'||$d['lifecycle_status']!=='issued'||$d['settlement_status']!=='paid'||(int)$d['paid_amount_base_unit']!==(int)$d['grand_total_base_unit'])throw new SalesValidationException('proforma_not_fully_paid',409);$set=json_decode((string)$d['settings_snapshot_json'],true,32,JSON_THROW_ON_ERROR)['settings'];$iid=Uuid::v4();$now=gmdate('Y-m-d H:i:s');$number=$this->nextNumber($b,'invoice',$set);$today=JalaliDate::today();$sql="INSERT INTO sales_documents (id,business_id,customer_id,document_type,lifecycle_status,settlement_status,document_number,source_document_id,is_official,national_id,customer_address,shipping_method,notes,issue_date,tax_rate_basis_points,tax_total_base_unit,currency_unit,subtotal_base_unit,discount_base_unit,surcharge_base_unit,grand_total_base_unit,paid_amount_base_unit,settings_snapshot_json,customer_snapshot_json,created_at,updated_at,issued_at) VALUES (?,?,?,'invoice','issued','paid',?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)";$this->pdo->prepare($sql)->execute([$iid,$b,$d['customer_id'],$number,$id,$d['is_official'],$d['national_id'],$d['customer_address'],$d['shipping_method'],$d['notes'],$today['date'],$d['tax_rate_basis_points'],$d['tax_total_base_unit'],$d['currency_unit'],$d['subtotal_base_unit'],$d['discount_base_unit'],$d['surcharge_base_unit'],$d['grand_total_base_unit'],$d['grand_total_base_unit'],$d['settings_snapshot_json'],$d['customer_snapshot_json'],$now,$now,$now]);$this->pdo->prepare('INSERT INTO sales_document_items (id,document_id,position,title,description,quantity_milli,unit_price_base_unit,discount_base_unit,tax_base_unit,line_total_base_unit,created_at,updated_at) SELECT UUID(),?,position,title,description,quantity_milli,unit_price_base_unit,discount_base_unit,tax_base_unit,line_total_base_unit,?,? FROM sales_document_items WHERE document_id=?')->execute([$iid,$now,$now,$id]);$this->snapshot($b,$iid,$now);$this->copyLogoSnapshot($b,$id,$iid,$now);$this->pdo->commit();}catch(\Throwable $e){$this->pdo->rollBack();throw$e;}return$this->get($b,$iid,false);}
 public function get(string $b,string $id,bool $payments=true):array{$d=$this->owned($b,$id);$items=$this->items($id);$p=[];if($payments&&$d['document_type']==='proforma'){$s=$this->pdo->prepare("SELECT id,amount_base_unit,paid_at,method,reference_text,note,status FROM payments WHERE business_id=? AND proforma_id=? ORDER BY paid_at,id");$s->execute([$b,$id]);$p=$s->fetchAll();}return$this->present($d,$items,$p);}
 public function list(string $b):array{$s=$this->pdo->prepare('SELECT id FROM sales_documents WHERE business_id=? ORDER BY created_at DESC LIMIT 50');$s->execute([$b]);return array_map(fn($r)=>$this->get($b,(string)$r['id'],false),$s->fetchAll());}
 public function deleteDraft(string $b,string $id):void{$d=$this->owned($b,$id);if($d['lifecycle_status']!=='draft')throw new SalesValidationException('issued_document_immutable',409);$this->pdo->prepare("DELETE FROM sales_documents WHERE id=? AND business_id=? AND lifecycle_status='draft'")->execute([$id,$b]);}
 public function cancel(string $b,string $id,array $in):array{self::keys($in,['reason']);$reason=self::text($in['reason']??'',500,'cancel_reason',true);$d=$this->owned($b,$id);if($d['lifecycle_status']==='cancelled')return$this->get($b,$id);if($d['lifecycle_status']!=='issued')throw new SalesValidationException('only_issued_document_cancellable',409);$linked=$this->pdo->prepare('SELECT 1 FROM sales_documents WHERE business_id=? AND source_document_id=? LIMIT 1');$linked->execute([$b,$id]);if($linked->fetchColumn())throw new SalesValidationException('linked_document_prevents_cancellation',409);$now=gmdate('Y-m-d H:i:s');$this->pdo->prepare("UPDATE sales_documents SET lifecycle_status='cancelled',cancelled_at=?,cancel_reason=?,version=version+1,updated_at=? WHERE id=? AND business_id=? AND lifecycle_status='issued'")->execute([$now,$reason,$now,$id,$b]);$this->snapshot($b,$id,$now);return$this->get($b,$id);}
 public function revise(string $b,string $id):array{$d=$this->owned($b,$id);if(!in_array($d['lifecycle_status'],['issued','cancelled'],true))throw new SalesValidationException('revision_requires_issued_document',409);$new=Uuid::v4();$now=gmdate('Y-m-d H:i:s');$sql="INSERT INTO sales_documents (id,business_id,customer_id,document_type,revision_of_document_id,is_official,national_id,customer_address,shipping_method,validity_days,notes,tax_rate_basis_points,tax_total_base_unit,currency_unit,subtotal_base_unit,discount_base_unit,surcharge_base_unit,grand_total_base_unit,created_at,updated_at) SELECT ?,business_id,customer_id,document_type,id,is_official,national_id,customer_address,shipping_method,validity_days,notes,tax_rate_basis_points,tax_total_base_unit,currency_unit,subtotal_base_unit,discount_base_unit,surcharge_base_unit,grand_total_base_unit,?,? FROM sales_documents WHERE id=? AND business_id=?";$this->pdo->beginTransaction();try{$this->pdo->prepare($sql)->execute([$new,$now,$now,$id,$b]);$this->pdo->prepare('INSERT INTO sales_document_items (id,document_id,position,title,description,quantity_milli,unit_price_base_unit,discount_base_unit,tax_base_unit,line_total_base_unit,created_at,updated_at) SELECT UUID(),?,position,title,description,quantity_milli,unit_price_base_unit,discount_base_unit,tax_base_unit,line_total_base_unit,?,? FROM sales_document_items WHERE document_id=?')->execute([$new,$now,$now,$id]);$this->pdo->commit();}catch(\Throwable $e){$this->pdo->rollBack();throw$e;}return$this->get($b,$new);}
 public function recordExport(string $b,string $id,array $in):array{self::keys($in,['format','byteSize']);$d=$this->owned($b,$id);if(!in_array($d['lifecycle_status'],['issued','cancelled'],true))throw new SalesValidationException('export_requires_issued_document',409);$format=(string)($in['format']??'');if(!in_array($format,['png','pdf','share'],true))throw new SalesValidationException('export_format_invalid');$bytes=Money::amount($in['byteSize']??null,'export_byte_size');if($bytes<1||$bytes>50_000_000)throw new SalesValidationException('export_byte_size_invalid');$snapshot=json_decode((string)$d['settings_snapshot_json'],true,32,JSON_THROW_ON_ERROR)['settings'];$template=(string)($snapshot['visual']['templateId']??'minimal');$exportId=Uuid::v4();$this->pdo->prepare('INSERT INTO document_exports (id,business_id,document_id,document_version,format,byte_size,template_id,template_version,created_at) VALUES (?,?,?,?,?,?,?,?,?)')->execute([$exportId,$b,$id,(int)$d['version'],$format,$bytes,$template,1,gmdate('Y-m-d H:i:s')]);return['id'=>$exportId,'format'=>$format];}
 private function resolveCustomer(string $b,array $c,string $name,string $phone,string $now):string{$id=$c['id']??null;if(is_string($id)&&$id!==''){$this->customer($b,$id);return$id;}CustomerDirectory::mobile($phone);$id=Uuid::v4();$this->pdo->prepare('INSERT INTO customers (id,business_id,display_name,phone,normalized_mobile,created_at,updated_at) VALUES (?,?,?,?,NULL,?,?)')->execute([$id,$b,$name,$phone,$now,$now]);return$id;}
