 private function owned(string $b,string $id,bool $lock=false):array{$s=$this->pdo->prepare('SELECT d.*,c.display_name AS customer_name,c.phone AS customer_phone FROM sales_documents d INNER JOIN customers c ON c.id=d.customer_id AND c.business_id=d.business_id WHERE d.id=? AND d.business_id=?'.($lock?' FOR UPDATE':''));$s->execute([$id,$b]);$r=$s->fetch();if(!$r)throw new SalesValidationException('document_not_found',404);return$r;}
 private function items(string $id):array{$s=$this->pdo->prepare('SELECT title,description,quantity_milli AS quantityMilli,unit_price_base_unit AS unitPriceBaseUnit,discount_base_unit AS discountBaseUnit,tax_base_unit AS taxBaseUnit,line_total_base_unit AS lineTotalBaseUnit,position FROM sales_document_items WHERE document_id=? ORDER BY position');$s->execute([$id]);return$s->fetchAll();}
 private function replaceItems(string $id,array $items,string $now):void{$this->pdo->prepare('DELETE FROM sales_document_items WHERE document_id=?')->execute([$id]);$s=$this->pdo->prepare('INSERT INTO sales_document_items (id,document_id,position,title,description,quantity_milli,unit_price_base_unit,discount_base_unit,tax_base_unit,line_total_base_unit,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?)');foreach($items as$i)$s->execute([Uuid::v4(),$id,$i['position'],$i['title'],$i['description'],$i['quantityMilli'],$i['unitPriceBaseUnit'],$i['discountBaseUnit'],$i['taxBaseUnit'],$i['lineTotalBaseUnit'],$now,$now]);}
 private function nextNumber(string $b,string $type,array $set):string{$this->pdo->prepare("INSERT INTO document_sequences (business_id,document_type,next_value) VALUES (?,?,1) ON DUPLICATE KEY UPDATE next_value=next_value")->execute([$b,$type]);$s=$this->pdo->prepare('SELECT next_value FROM document_sequences WHERE business_id=? AND document_type=? FOR UPDATE');$s->execute([$b,$type]);$n=(int)$s->fetchColumn();$this->pdo->prepare('UPDATE document_sequences SET next_value=next_value+1 WHERE business_id=? AND document_type=?')->execute([$b,$type]);$d=$set['document']??[];$prefix=$type==='proforma'?($d['proformaPrefix']??'PF'):($d['invoicePrefix']??'INV');return(string)$prefix.'-'.str_pad((string)$n,(int)($d['numberPadding']??5),'0',STR_PAD_LEFT);}
 private function snapshotLogo(string $b,string $id,string $now):void{$s=$this->pdo->prepare('SELECT mime_type,byte_size,image_bytes FROM '.((bool)$this->owned($b,$id)['is_official']?'business_official_logo_assets':'business_logo_assets').' WHERE business_id=? LIMIT 1');$s->execute([$b]);if($logo=$s->fetch())$this->pdo->prepare('INSERT INTO sales_document_logo_snapshots (document_id,business_id,mime_type,byte_size,image_bytes,created_at) VALUES (?,?,?,?,?,?)')->execute([$id,$b,$logo['mime_type'],$logo['byte_size'],$logo['image_bytes'],$now]);}
 private function copyLogoSnapshot(string $b,string $source,string $target,string $now):void{$this->pdo->prepare('INSERT INTO sales_document_logo_snapshots (document_id,business_id,mime_type,byte_size,image_bytes,created_at) SELECT ?,business_id,mime_type,byte_size,image_bytes,? FROM sales_document_logo_snapshots WHERE document_id=? AND business_id=?')->execute([$target,$now,$source,$b]);}
 public function getLogo(string $b,string $id):?array{$this->owned($b,$id);$s=$this->pdo->prepare('SELECT mime_type AS mimeType,byte_size AS byteSize,image_bytes AS bytes FROM sales_document_logo_snapshots WHERE document_id=? AND business_id=?');$s->execute([$id,$b]);$logo=$s->fetch();return$logo?:null;}
 private function snapshot(string $b,string $id,string $now):void{$full=['document'=>$this->owned($b,$id),'items'=>$this->items($id)];$this->pdo->prepare('INSERT INTO sales_document_snapshots (id,document_id,version,snapshot_json,created_at) VALUES (?,?,?,?,?)')->execute([Uuid::v4(),$id,1,json_encode($full,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR),$now]);}
 private function present(array $d,array $items,array $p):array{$total=(int)$d['grand_total_base_unit'];$paid=(int)$d['paid_amount_base_unit'];$date=$d['issue_date']?JalaliDate::format(new \DateTimeImmutable($d['issue_date'])):null;$until=$d['valid_until']?JalaliDate::format(new \DateTimeImmutable($d['valid_until'])):null;$out=['id'=>$d['id'],'customerId'=>$d['customer_id'],'customerName'=>$d['customer_name'],'customerPhone'=>$d['customer_phone'],'documentType'=>$d['document_type'],'lifecycleStatus'=>$d['lifecycle_status'],'settlementStatus'=>$d['settlement_status'],'documentNumber'=>$d['document_number'],'sourceDocumentId'=>$d['source_document_id'],'revisionOfDocumentId'=>$d['revision_of_document_id']??null,'cancelledAt'=>$d['cancelled_at']??null,'cancelReason'=>$d['cancel_reason']??null,'isOfficial'=>(bool)$d['is_official'],'nationalId'=>$d['national_id'],'customerAddress'=>$d['customer_address'],'shippingMethod'=>$d['shipping_method'],'validityDays'=>$d['validity_days']!==null?(int)$d['validity_days']:null,'notes'=>$d['notes'],'issueDate'=>$date,'validUntil'=>$until,'taxRateBasisPoints'=>(int)$d['tax_rate_basis_points'],'taxTotalBaseUnit'=>(string)$d['tax_total_base_unit'],'currencyUnit'=>$d['currency_unit'],'subtotalBaseUnit'=>(string)$d['subtotal_base_unit'],'discountBaseUnit'=>(string)$d['discount_base_unit'],'surchargeBaseUnit'=>(string)$d['surcharge_base_unit'],'grandTotalBaseUnit'=>(string)$total,'paidAmountBaseUnit'=>(string)$paid,'remainingAmountBaseUnit'=>(string)max(0,$total-$paid),'version'=>(int)$d['version'],'items'=>$items,'canIssueFinalInvoice'=>$d['document_type']==='proforma'&&$d['lifecycle_status']==='issued'&&$paid===$total];if($d['settings_snapshot_json'])$out['settingsSnapshot']=json_decode((string)$d['settings_snapshot_json'],true,32,JSON_THROW_ON_ERROR)['settings'];if($d['customer_snapshot_json']){$customer=json_decode((string)$d['customer_snapshot_json'],true,16,JSON_THROW_ON_ERROR);$out['customerName']=$customer['displayName']??$out['customerName'];$out['customerPhone']=$customer['phone']??$out['customerPhone'];}$logo=$this->pdo->prepare('SELECT 1 FROM sales_document_logo_snapshots WHERE document_id=? AND business_id=?');$logo->execute([$d['id'],$d['business_id']]);$out['logoPresent']=(bool)$logo->fetchColumn();if($d['document_type']==='proforma')$out['payments']=$p;return$out;}
 private function assertOfficialProfile(string $b,array $set):void{$seller=$set['officialSeller']??[];$accounts=$set['officialPayment']['accounts']??[];$complete=trim((string)($seller['companyName']??''))!==''&&trim((string)($seller['address']??''))!==''&&trim((string)($seller['phone']??''))!==''&&trim((string)($seller['nationalId']??''))!==''&&is_array($accounts)&&count($accounts)>0;foreach($accounts as$a){$complete=$complete&&trim((string)($a['sheba']??''))!==''&&trim((string)($a['accountHolder']??''))!=='';}if($complete){$q=$this->pdo->prepare('SELECT 1 FROM business_official_logo_assets WHERE business_id=?');$q->execute([$b]);$complete=(bool)$q->fetchColumn();}if(!$complete)throw new SalesValidationException('official_profile_incomplete',409);}
